import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Translation status","description":"Scope of canonical UIX documentation updates reviewed in German, English and French.","frontmatter":{"title":"Translation status","description":"Scope of canonical UIX documentation updates reviewed in German, English and French."},"headers":[],"relativePath":"en/projects/uix/translation-status.md","filePath":"en/projects/uix/translation-status.md","lastUpdated":1794126124000}'),n={name:"en/projects/uix/translation-status.md"};function i(s,e,c,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="translation-status" tabindex="-1">Translation status <a class="header-anchor" href="#translation-status" aria-label="Permalink to &quot;Translation status&quot;">​</a></h1><h2 id="review-on-7-november-2026-desktop-tabs-in-preview-9-1-0-beta-0" tabindex="-1">Review on 7 November 2026: desktop tabs in preview 9.1.0-beta.0 <a class="header-anchor" href="#review-on-7-november-2026-desktop-tabs-in-preview-9-1-0-beta-0" aria-label="Permalink to &quot;Review on 7 November 2026: desktop tabs in preview 9.1.0-beta.0&quot;">​</a></h2><p>Reviewed notifications: <a href="https://github.com/Lint-Free-Technology/uix/commit/1d53592b241ec8666b34d67056671bb37d1c2a1f" target="_blank" rel="noreferrer">1d53592</a> / <a href="https://github.com/Lint-Free-Technology/uix/commit/e7b5bdd811a53960e9559c53a354c7855c537286" target="_blank" rel="noreferrer">e7b5bdd</a>. The complete archived <code>dev</code> source tree contains <strong>65</strong> canonical Markdown pages. Only <a href="./extras/custom-sidebar-panels">Custom sidebar panels</a> changed in content since <code>f63ebbd</code>; 64 pages, navigation and media are unchanged. Content comparison accounts for different line endings.</p><p><strong>Open in new tab (desktop only)</strong> applies to internal HA paths in desktop browsers. Companion navigates within the app; website URLs do not use this option. If the desktop browser blocks the new tab, the HA path opens in the current tab. This new behavior is explicitly documented <strong>from 9.1.0-beta.0</strong>. <strong>9.0.0 / HA 2026.11.0 or later</strong> remains the stable baseline; the preview is not presented as a stable release.</p><p>EN is synchronized with the changed source page; DE/FR and their overviews are updated. Unchanged English pages retain their still-valid older source notices. Source and translation manifests are updated. This is a documentation review, not a new HA runtime test.</p><h2 id="review-of-5-november-2026-against-uix-9-0-0" tabindex="-1">Review of 5 November 2026 against UIX 9.0.0 <a class="header-anchor" href="#review-of-5-november-2026-against-uix-9-0-0" aria-label="Permalink to &quot;Review of 5 November 2026 against UIX 9.0.0&quot;">​</a></h2><p>All <strong>65</strong> canonical source pages were compared with <a href="https://github.com/Lint-Free-Technology/uix/commit/f63ebbdda5294fe0b9d31d89d4942496ebe55722" target="_blank" rel="noreferrer"><code>master f63ebbd</code></a>. Since our recorded <code>e4a1caa</code> baseline, <strong>eight pages changed</strong> and 57 remained identical. <code>dev ef414d9</code> contains identical documentation, including navigation and media. Notifications <code>fa4a427</code>, <code>5c253f9</code>, <code>4768bff</code>, <code>f63ebbd</code> and <code>99293d1</code> are covered. No additional documentation differences were found on the current branches.</p><ul><li><strong>UIX 9.0.0</strong> became stable on 4 November 2026 and requires <strong>Home Assistant 2026.11.0 or later</strong>. Current pages now identify the former preview features as stable.</li><li><strong>Marketplace</strong> installs UIX and adds its service. Manual setup has separate instructions. Marketplace removal also removes Foundries, custom sidebar panels and service settings.</li><li><strong>Frame panels</strong> now use <code>a0d7b954_tailscale</code> in the example. The former HACS styling example was removed from the current reference.</li><li><strong>Contributions</strong> distinguish <code>feat!:</code>/<code>BREAKING CHANGE: ...</code> for major releases from <code>feat(major):</code> for minor releases.</li><li><strong>Forge, popover timeout and sidebar links</strong> are stable 9.0.0 features. Landing pages, footers, metadata and the English source mirror are synchronized. The notified Forge animation was checked against the source.</li></ul><p>The previous documentation and original sources were backed up. Verification covers source changes, translations, technical identifiers, code, media and links. This documentation review does not include a Home Assistant runtime test.</p><h2 id="review-of-2-november-2026-9-0-0-beta-8-preview" tabindex="-1">Review of 2 November 2026: 9.0.0-beta.8 preview <a class="header-anchor" href="#review-of-2-november-2026-9-0-0-beta-8-preview" aria-label="Permalink to &quot;Review of 2 November 2026: 9.0.0-beta.8 preview&quot;">​</a></h2><p>Notifications <code>f769f06</code>, <code>2782a71</code>, <code>1f69b99</code> and <code>e4a1caa</code> were reviewed through <a href="https://github.com/Lint-Free-Technology/uix/commit/e4a1caa6437f88282cfe04d768d3c11df387fc42" target="_blank" rel="noreferrer">canonical revision e4a1caa</a>. Comparing all <strong>65</strong> source pages identified three changed pages and one relocated page. English is synchronized; German and French cover the changes.</p><ul><li><a href="./extras/uix-actions#popover-show-an-anchored-home-assistant-popover">Popover timeout</a>, from <strong>beta.7</strong>: milliseconds, <code>0</code>–<code>2147483647</code>, individual timer unaffected by interaction, no footer actions or form submission on expiry.</li><li><a href="./extras/custom-sidebar-panels">Custom sidebar panels</a>, external targets and new tabs from <strong>beta.8</strong>: accepted URL schemes, return to the previous HA page, and current-tab fallback when blocked.</li><li>Page/navigation moved to <strong>Extras</strong>; old routes remain as compatibility links. Landing pages, footers and review records updated. Reviewed cache clarification preserved.</li><li><strong>Stable remains 8.4.0 / HA 2026.10.0 minimum</strong>. New preview additions require <strong>HA 2026.11.0b0 or later</strong>. Historical feature versions remain unchanged.</li></ul><p>Previous sources backed up. Source, identifier, code-example, build and link checks; no HA runtime test.</p><h2 id="review-of-31-october-2026-65-source-pages-9-0-0-beta-6-preview" tabindex="-1">Review of 31 October 2026: 65 source pages, 9.0.0-beta.6 preview <a class="header-anchor" href="#review-of-31-october-2026-65-source-pages-9-0-0-beta-6-preview" aria-label="Permalink to &quot;Review of 31 October 2026: 65 source pages, 9.0.0-beta.6 preview&quot;">​</a></h2><p>The notified revisions <a href="https://github.com/Lint-Free-Technology/uix/commit/964f4402b6f263a5deac53327b825a85cb3e3e72" target="_blank" rel="noreferrer"><code>964f440</code></a>, <a href="https://github.com/Lint-Free-Technology/uix/commit/e6fb84dd715ea4bac9a330357705897ea8d44690" target="_blank" rel="noreferrer"><code>e6fb84d</code></a> and <a href="https://github.com/Lint-Free-Technology/uix/commit/25aec397f873e566c2ead0201d819595854405ab" target="_blank" rel="noreferrer"><code>25aec39</code></a> were compared with the previous reviewed source. All <strong>65</strong> source paths are covered. English was synchronized; German and French cover the actual content changes.</p><ul><li>Complete translated <a href="./using/custom-sidebar-panels">custom sidebar panels</a> page, available <strong>from 9.0.0-beta.6</strong>, including setup, administrator option, internal targets, stable URLs, editing/deleting, personal order and history behavior. Added to indexes and navigation.</li><li>Forge migration explicitly names <strong>Convert to visual editor</strong> and moves only <code>element.type</code> to <code>element_base.type</code>.</li><li>Upstream also removed the forced automation YAML-mode examples. DE/FR retain them only in a clearly historical collapsed section for existing links.</li><li>Landing pages, footers, review records and <code>llms.txt</code> now agree. <strong>Stable remains 8.4.0</strong>, released 7 October 2026, revision <code>71b8ccd</code>, requiring <strong>Home Assistant 2026.10.0</strong>. <strong>9.0.0-beta.6 / e6fb84d</strong> identifies the separately reviewed documentation preview. Historical introduction versions and cache clarifications are preserved.</li></ul><p>Backed up before editing. Source comparison, page coverage, technical identifiers, build and local links/language metadata are checked; unchanged pages were not retranslated and no Home Assistant runtime test was performed.</p><h2 id="content-review-of-27-october-2026" tabindex="-1">Content review of 27 October 2026 <a class="header-anchor" href="#content-review-of-27-october-2026" aria-label="Permalink to &quot;Content review of 27 October 2026&quot;">​</a></h2><p>The remaining DE/EN/FR inventory findings have <a href="/documentation-review.json">individual assessments</a>. The canonical English preview is retained. Two contradictory cache paragraphs were corrected against the implementation: <code>clear-cache</code> preserves <code>localStorage</code> and the Browser Mod identity. The source/code record now explicitly documents these editorial corrections.</p><p>Eighteen French reference pages include 199 additional configurations from the German examples, with French headings and unchanged technical values. Missing theme, Foundry, DOM-path and browser-override explanations were added, and a remaining English theme paragraph was translated into French. Historical version annotations and different editorial structures are recorded as reviewed differences. Stable and preview documentation remain distinct. This review does not constitute a new Home Assistant runtime test.</p><h2 id="translation-content-review-—-26-october-2026" tabindex="-1">Translation content review — 26 October 2026 <a class="header-anchor" href="#translation-content-review-—-26-october-2026" aria-label="Permalink to &quot;Translation content review — 26 October 2026&quot;">​</a></h2><p>All <strong>64 canonical pages</strong> were checked again against <a href="https://github.com/Lint-Free-Technology/uix/tree/26e54e6d4973231a393933e6479ed1b03cc86cd3/docs/source" target="_blank" rel="noreferrer">English source <code>26e54e6</code></a>. The <code>dev</code> source has not changed since the previous review; the original website still identifies <strong>9.0.0-beta.2</strong>. The stable baseline remains <strong>8.4.0</strong>.</p><ul><li>Corrected German section-background variables/configuration, the <code>custom:mod-card</code> fallback warning, template-debug marker and 20-second cache cooldown.</li><li>Added full Badge and Broker Badge/Lock/Action Handler examples in DE/FR. Corrected the French Tooltip arrow-size theme fallback and added its theme-debugging context.</li><li>Expanded German Foundry anchors/includes/secrets/merge and empty-billet examples, throttling, section/footer constraints, Background adapters, Map filtering, Event merging and embedded More-info. Corrected Lock/Overlay position defaults and Overlay border radius.</li><li>The <a href="/projects/uix/translation-review.json">page review record</a> preserves source and translation hashes. Page counterparts, table keys and the added examples were checked; build/link/media/language checks run separately. Copied technical examples and configuration identifiers retain their original spelling.</li></ul><p>DE/FR remain editorial translations with some condensed sections. This is not independent translation certification or a Home Assistant runtime test. EN language navigation continues to open the original documentation in a separate tab.</p><h2 id="full-review-—-22-october-2026" tabindex="-1">Full review — 22 October 2026 <a class="header-anchor" href="#full-review-—-22-october-2026" aria-label="Permalink to &quot;Full review — 22 October 2026&quot;">​</a></h2><p>All <strong>64 canonical Markdown pages</strong> were compared against frozen <a href="https://github.com/Lint-Free-Technology/uix/tree/26e54e6d4973231a393933e6479ed1b03cc86cd3/docs/source" target="_blank" rel="noreferrer">English revision <code>26e54e6</code></a>. Since the previous <code>e2e0701</code> preview review, only the Forge reference, Foundries and Forge overview changed; the other 61 source pages are unchanged. The stable release remains <strong>8.4.0</strong>; the reviewed preview is <strong>9.0.0-beta.2</strong>.</p><ul><li><strong>EN:</strong> all 64 pages now contain the full original English content instead of placeholders. Admonitions, anchors, links and media are adapted for this site with CC BY 4.0 attribution. The <a href="/projects/uix/canonical-review.json">review manifest</a> records source/output hashes; code blocks are compared with normalized outer indentation, trailing whitespace and line endings.</li><li><strong>DE/FR:</strong> added Broker Badge, Text content, Lock and Action handler; extended Forge type anchors, Foundry native bases and blank badges. French Tooltip gains missing options, scrolling and current CSS defaults.</li><li><strong>DE:</strong> corrected Foundry examples (<code>uix_foundries</code>, top-level <code>foundry</code>, <code>forge.billets</code>, Native type matching, Spark merging and macro <code>returns</code>) and Card-mod compatibility/migration FAQ through 4.2.1. Added browser event actions, cache retention, integration dependencies, state throttling, billet precedence and missing Spark CSS options.</li><li>Every canonical page has DE/EN/FR counterparts. The legacy English <code>style-custom-panels</code> route links to <code>style-frame-panels</code>. Missing original media are included; language links, references and local images are checked.</li></ul><p>This is a source/content/documentation review. DE/FR remain editorial translations rather than line-identical copies or independently certified translations. No HA system was accessed or changed. Stable metadata remains 8.4.0; preview version/revision are separate. The earlier targeted Forge review is preserved below as history.</p><h2 id="forge-review-—-22-october-2026" tabindex="-1">Forge review — 22 October 2026 <a class="header-anchor" href="#forge-review-—-22-october-2026" aria-label="Permalink to &quot;Forge review — 22 October 2026&quot;">​</a></h2><p>Canonical <code>dev</code> <a href="https://github.com/Lint-Free-Technology/uix/commit/1badf70befb9c9d3d7b06c0eced75af7d552aff1" target="_blank" rel="noreferrer">change <code>1badf70befb9</code></a> adds the Forge visual editor availability note for <strong>9.0.0-beta.2</strong>. Our pages lacked the corresponding editor section. A source-reviewed summary now covers Native, Forge, Element, Foundry and Export in <strong>DE/EN/FR</strong>, including <code>element_base</code>/<code>element</code>, type anchors, null/disable semantics and YAML-only limits.</p><p>The English Forge page is no longer a placeholder for this section. The full canonical reference remains linked. This is not a complete retranslation of all UIX pages or all <code>dev</code> changes. Stable baseline, release metadata and footer remain unchanged; the previous broader preview review through 9.0.0-beta.0 is separate from this targeted Forge review. Documentation-only update, without HA installation or runtime testing.</p><p>Earlier review history remains on the <a href="/projects/uix/translation-status">German status page</a> and <a href="/fr/projects/uix/translation-status">French status page</a>.</p>',32)])])}const u=a(n,[["render",i]]);export{p as __pageData,u as default};
